There's no existing project here, so I'll show you the implementation pattern directly.

**Use `IExceptionHandler` (ASP.NET Core 8+) with `ProblemDetails` services:**

```csharp
// Program.cs
var builder = WebApplication.CreateBuilder(args);

// Register ProblemDetails services
builder.Services.AddProblemDetails();

// Register your custom exception handler
builder.Services.AddExceptionHandler<GlobalExceptionHandler>();

var app = builder.Build();

// Add the middleware (order matters — before routing)
app.UseExceptionHandler();

app.MapGet("/example", () => { /* your endpoints */ });

app.Run();
```

```csharp
// GlobalExceptionHandler.cs
using Microsoft.AspNetCore.Diagnostics;
using Microsoft.AspNetCore.Mvc;

public class GlobalExceptionHandler : IExceptionHandler
{
    private readonly ILogger<GlobalExceptionHandler> _logger;

    public GlobalExceptionHandler(ILogger<GlobalExceptionHandler> logger)
    {
        _logger = logger;
    }

    public async ValueTask<bool> TryHandleAsync(
        HttpContext httpContext,
        Exception exception,
        CancellationToken cancellationToken)
    {
        var (statusCode, title) = exception switch
        {
            KeyNotFoundException => (StatusCodes.Status404NotFound, "Not Found"),
            ArgumentException => (StatusCodes.Status400BadRequest, "Bad Request"),
            InvalidOperationException => (StatusCodes.Status409Conflict, "Conflict"),
            _ => (StatusCodes.Status500InternalServerError, "Internal Server Error")
        };

        _logger.LogError(exception, "Exception occurred: {Message}", exception.Message);

        var problemDetails = new ProblemDetails
        {
            Status = statusCode,
            Title = title,
            Detail = statusCode == StatusCodes.Status500InternalServerError
                ? "An unexpected error occurred."  // Hide sensitive details
                : exception.Message,
            Instance = httpContext.Request.Path
        };

        httpContext.Response.StatusCode = statusCode;
        await httpContext.Response.WriteAsJsonAsync(problemDetails, cancellationToken);

        return true; // Signal that the exception is handled
    }
}
```

**How it works:**

| Exception | Status | Detail |
|-----------|--------|--------|
| `KeyNotFoundException` | 404 | Exception message |
| `ArgumentException` | 400 | Exception message |
| `InvalidOperationException` | 409 | Exception message |
| Anything else | 500 | Generic message (no leak) |

**Key points:**
- `IExceptionHandler` (added in .NET 8) replaces the older lambda-based `UseExceptionHandler` approach
- `AddProblemDetails()` ensures non-exception error responses (e.g., 404 from routing) also use RFC 7807 format
- No try-catch needed in endpoints — the middleware catches everything globally
- You can register multiple `IExceptionHandler` implementations; they're called in registration order until one returns `true`
